def summarize_hci(df):
    a=df[df.condition!='no_ai']; good=a[(a.ai_correct==1)&(a.clinician_initial!=a.ai_prediction)]; bad=a[(a.ai_correct==0)&(a.clinician_initial!=a.ai_prediction)]
    return {'n_cases':len(df),'initial_accuracy':df.initial_correct.mean(),'final_accuracy':df.final_correct.mean(),'switch_rate':df.decision_switched.mean(),'final_ai_agreement_rate':a.ai_agreement_final.mean(),'appropriate_reliance_rate':((good.clinician_final==good.ai_prediction).mean() if len(good) else 0),'inappropriate_reliance_rate':((bad.clinician_final==bad.ai_prediction).mean() if len(bad) else 0),'mean_confidence_change':(df.clinician_final_confidence-df.clinician_initial_confidence).mean(),'explanation_open_rate':df.loc[df.condition=='ai_plus_explanation','explanation_opened'].mean(),'mean_decision_time_sec':df.decision_time_sec.mean()}
